"""Generate docs/source-coverage.md from the live adapter registry (single source of truth)."""

from __future__ import annotations

import sys
from collections import defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from integrations.sources.registry import build_default_registry  # noqa: E402
from shared.types import IdentifierType  # noqa: E402


def main() -> None:
    reg = build_default_registry(load_plugins=False)
    adapters = reg.all()
    lines = [
        "# Source coverage report",
        "",
        "_Generated by `scripts/generate_source_coverage.py` from the adapter registry – do not edit by hand._",
        "",
        f"ATLAS ships **{len(adapters)} source adapters**. Coverage is limited to these sources; ATLAS does not",
        "claim to search the whole internet. Each investigation's report lists which sources were consulted and",
        "what each one returned (ok, no results, skipped, not configured, rate-limited, unavailable, error).",
        "",
        "Reliability grades: **A** authoritative primary source · **B** usually reliable (platform about its own",
        "users) · **C** fairly reliable aggregator · **D** not usually reliable (index / crawl) · **E** unknown.",
        "",
        "## Coverage by input type",
        "",
        "| Input type | Sources |",
        "|---|---|",
    ]
    for t in IdentifierType:
        names = [a.meta.name for a in reg.for_input(t)]
        lines.append(f"| {t.value} | {', '.join(f'`{n}`' for n in names) or '—'} |")
    by_cat: dict[str, list] = defaultdict(list)
    for a in adapters:
        by_cat[a.meta.category.value].append(a)
    lines += ["", "## Adapters", ""]
    lines += [
        "| Source | Category | Inputs | Access | Auth | Rate limit | Reliability | Licence | Default | Flags |",
        "|---|---|---|---|---|---|---|---|---|---|",
    ]
    for a in adapters:
        m = a.meta
        auth = "none"
        if m.auth.required:
            auth = "required: " + ", ".join(f"`ATLAS_{f.upper()}`" for f in m.auth.settings_fields)
        elif m.auth.settings_fields:
            auth = "optional: " + ", ".join(f"`ATLAS_{f.upper()}`" for f in m.auth.settings_fields)
        flags = []
        if m.legal.requires_subject_consent:
            flags.append("consent required")
        if m.legal.active_probe:
            flags.append("active · scope required")
        if m.legal.contains_personal_data:
            flags.append("personal data")
        rl = "offline" if m.rate_limit.requests == 0 else f"{m.rate_limit.requests}/{m.rate_limit.per_seconds:g}s"
        lines.append(
            f"| [{m.display_name}]({m.homepage}) (`{m.name}`) | {m.category.value} | "
            f"{', '.join(t.value for t in m.input_types)} | {m.access_method.value} | {auth} | {rl} | "
            f"{m.reliability.value} | {m.legal.license or 'see terms'} | {'on' if m.default_enabled else 'off'} | "
            f"{', '.join(flags) or '—'} |"
        )
    lines += ["", "## Details", ""]
    for a in adapters:
        m = a.meta
        lines += [
            f"### {m.display_name} (`{m.name}`)",
            "",
            m.description,
            "",
            f"- **Freshness:** {m.freshness}",
            f"- **Restrictions:** {m.legal.restrictions}",
            f"- **Terms:** {m.legal.terms_url or 'n/a'}",
            f"- **Fields collected:** {', '.join(f'`{f}`' for f in m.fields)}",
            f"- **Citation format:** `{m.citation_format}`",
        ]
        if m.auth.how_to_obtain:
            lines.append(f"- **Credentials:** {m.auth.how_to_obtain}")
        lines.append("")
    (ROOT / "docs" / "source-coverage.md").write_text("\n".join(lines).rstrip() + "\n")
    print(f"wrote docs/source-coverage.md ({len(adapters)} adapters)")


if __name__ == "__main__":
    main()
